head.script:
scwin.getToday = function() {
    var date = new Date();
    var mm = date.getMonth() > 8 ? date.getMonth() + 1 : '0' + (date.getMonth() + 1);
    return parseInt(mm);
}
scwin.checkVal1 = function() {
    return (document.getElementById('wq_uuid_1_calendar_selectbox_month_label') || document.getElementById('mf_wq_uuid_1_calendar_selectbox_month_label')).innerText == (scwin.getToday()+1+'월');
}
scwin.checkVal2 = function() {
    debugger;
    if (scwin.getToday() == 12)
        return (1 + '월') === (document.getElementById('wq_uuid_1_calendar_selectbox_month_label') || document.getElementById('mf_wq_uuid_1_calendar_selectbox_month_label')).innerText;
    else
        return (scwin.getToday() + 1 + '월') === (document.getElementById('wq_uuid_1_calendar_selectbox_month_label') || document.getElementById('mf_wq_uuid_1_calendar_selectbox_month_label')).innerText;
}

scwin.onpageload = function() {
}
